command($script = @'
import os
import re

def unwrap_paragraph(paragraph):
    # Don't unwrap if it starts with special markdown tokens
    lines = paragraph.split('\n')
    if not lines:
        return ""
    first = lines[0].lstrip()
    # Check if header, table row, list item, blockquote, or horizontal rule
    if any(first.startswith(prefix) for prefix in ['#', '|', '---', '***', '___', '>', '```', '~~~', '<']):
        return paragraph
    if re.match(r'^(\*|-|\+|\d+\.)\s', first):
        # Could be a list with wrapped lines, unwrap lines within list items
        unwrapped_items = []
        for line in lines:
            if re.match(r'^(\s*)(\*|-|\+|\d+\.)\s', line):
                unwrapped_items.append('\n' + line)
            elif line.startswith('    ') or line.startswith('\t'):
                # Indented block or continuation
                if unwrapped_items:
                    unwrapped_items[-1] += ' ' + line.strip()
                else:
                    unwrapped_items.append(line)
            else:
                if unwrapped_items:
                    unwrapped_items[-1] += ' ' + line.strip()
                else:
                    unwrapped_items.append(line)
        return '\n'.join(x.lstrip('\n') for x in unwrapped_items)

    # Normal prose paragraph: join lines with spaces
    joined = ' '.join(l.strip() for l in lines)
    return joined

def unwrap_markdown(content):
    # Preserve yaml frontmatter
    frontmatter = ""
    rest = content
    if content.startswith('---'):
        parts = content.split('---', 2)
        if len(parts) >= 3:
            frontmatter = f"---{parts[1]}---\n\n"
            rest = parts[2].lstrip('\r\n')

    # Split by code blocks
    code_block_pattern = re.compile(r'(```[\s\S]*?```|~~~[\s\S]*?~~~)')
    tokens = code_block_pattern.split(rest)

    new_tokens = []
    for i, token in enumerate(tokens):
        if i % 2 == 1:
            # Code block, preserve verbatim
            new_tokens.append(token)
        else:
            # Markdown text: split by blank lines into paragraphs
            paragraphs = re.split(r'\n\s*\n', token)
            unwrapped_paras = [unwrap_paragraph(p) for p in paragraphs]
            new_tokens.append('\n\n'.join(p for p in unwrapped_paras if p is not None))

    return frontmatter + ''.join(new_tokens)

target_dirs = [
    r"c:\Users\johng\.gemini\config\plugins\elephant-goldfish-model\agents",
    r"c:\Users\johng\.gemini\config\plugins\elephant-goldfish-model\docs",
    r"c:\Users\johng\.gemini\config\plugins\elephant-goldfish-model\skills",
    r"c:\Users\johng\.gemini\config\plugins\elephant-goldfish-model\resources"
]

for d in target_dirs:
    for root, _, files in os.walk(d):
        for f in files:
            if f.endswith('.md'):
                fpath = os.path.join(root, f)
                with open(fpath, 'r', encoding='utf-8') as fp:
                    content = fp.read()
                unwrapped = unwrap_markdown(content)
                with open(fpath, 'w', encoding='utf-8') as fp:
                    fp.write(unwrapped)

print("Unwrapping complete.")
'@

