foreach ($s in $skills) {
  $skillFile = Join-Path $s.FullName "SKILL.md"
  if (Test-Path $skillFile) {
    $content = Get-Content $skillFile -Raw
    # If frontmatter has description: >-\n  something\n  something
    if ($content -match '(?s)^---\r?\n(.*?)\r?\n---') {
      $fm = $matches[1]
      $rest = $content.Substring($matches[0].Length)
      # Unwrap description inside frontmatter
      if ($fm -match '(?s)description:\s*(?:>-\s*|\|\s*)?\r?\n((?:[ \t]+[^\r\n]+\r?\n)+)') {
        $descBlock = $matches[1]
        $unwrappedDesc = ($descBlock -split '\r?\n' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne "" }) -join " "
        $newFm = $fm -replace '(?s)description:\s*(?:>-\s*|\|\s*)?\r?\n(?:[ \t]+[^\r\n]+\r?\n)+', "description: $unwrappedDesc`r`n"
        $newContent = "---`r`n$newFm`r`n---$rest"
        Set-Content -Path $skillFile -Value $newContent -Encoding utf8
      }
    }
  }
})

